const fs=require("fs");
const files=["a.txt","b.txt","c.txt"];
const re=/^\s*([A-Za-z][A-Za-z ]*?)\s*population\s*:\s*(-?\d+)\s*$/i;
const records=[]; const problems=[]; const missing=[];
for (const f of files) {
  let s;
  try { s=fs.readFileSync(f,"utf8"); } catch(e){ missing.push(f); continue; }
  const lines=s.split(/\r?\n/);
  let hits=0;
  lines.forEach((line,i)=>{
    if (!line.trim()) return;
    const m=line.match(re);
    if (m) { hits++; records.push({file:f,line:i+1,label:m[1].trim(),value:Number(m[2])}); }
    else problems.push(`unparsed content ${f}:${i+1}: ${JSON.stringify(line)}`);
  });
  if (hits===0) problems.push(`no population entry in ${f}`);
  if (hits>1) problems.push(`duplicate population entries in ${f} (${hits})`);
}
console.log("missing files:", missing.length?missing:"none");
console.log("records:"); console.table(records);
const seen=new Map();
for (const r of records){
  const key=r.label.toLowerCase();
  if (seen.has(key)) problems.push(`duplicate label "${r.label}" in ${r.file} (also ${seen.get(key).file})`);
  else seen.set(key,r);
  if (!Number.isInteger(r.value)) problems.push(`non-integer population in ${r.file}`);
}
const distinct=new Set(records.map(r=>r.label.toLowerCase()));
if (distinct.size!==records.length) problems.push("labels not unique across sources");
console.log("distinct labels:", [...distinct].join(", "));
console.log("all sources present:", missing.length===0 && records.length===files.length);
console.log("problems:", problems.length?problems:"none");
'

