const fs = require("fs");
const files = ["a.txt", "b.txt", "c.txt"];
const pops = files.map(f => {
  const txt = fs.readFileSync(f, "utf8").trim();
  const m = txt.match(/^([A-Za-z]+) population:\s*(-?\d+(?:\.\d+)?)$/);
  if (!m) throw new Error(`unparseable population in ${f}: ${JSON.stringify(txt)}`);
  return { file: f, label: m[1], population: Number(m[2]) };
});
for (const p of pops) console.log(`${p.file}: ${p.label} = ${p.population}`);
const total = pops.reduce((s, p) => s + p.population, 0);
console.log("total =", total);
fs.writeFileSync("answer.json", JSON.stringify({ total }, null, 2) + "\n");
console.log("wrote answer.json");
'

